from copy import deepcopy
from numbers import Real


class SampleCatalog:
    def __init__(self, samples, transform=None):
        if not isinstance(samples, list):
            raise ValueError("samples must be a list")
        if transform is not None and not callable(transform):
            raise TypeError("transform must be callable or None")
        required = {"values", "points", "label"}
        for sample in samples:
            if not isinstance(sample, dict) or set(sample) != required:
                raise ValueError("invalid sample fields")
            values = sample["values"]
            points = sample["points"]
            if not isinstance(values, list) or not values:
                raise ValueError("values must be a non-empty list")
            if any(isinstance(value, bool) or not isinstance(value, Real) for value in values):
                raise ValueError("values must contain numbers")
            if not isinstance(points, list):
                raise ValueError("points must be a list")
            for point in points:
                if not isinstance(point, list) or len(point) != 2:
                    raise ValueError("each point must have two coordinates")
                if any(isinstance(value, bool) or not isinstance(value, Real) for value in point):
                    raise ValueError("coordinates must be numbers")
        self._samples = deepcopy(samples)
        self._transform = transform

    def __len__(self):
        return len(self._samples)

    def __getitem__(self, index):
        if isinstance(index, bool) or not isinstance(index, int):
            raise TypeError("index must be an integer")
        if index < -len(self._samples) or index >= len(self._samples):
            raise IndexError("sample index out of range")
        result = self._samples[index]
        if self._transform is not None:
            result = self._transform(result)
            if not isinstance(result, dict) or set(result) != {"values", "points", "label"}:
                raise ValueError("transform returned an invalid sample")
            result = deepcopy(result)
        return result

